List<int> pluck(List<int> arr) {
  if (arr.isEmpty) return [];

  List<int> evens = arr.where((x) => x % 2 == 0).toList();
  if (evens.isEmpty) return [];

  int minEven = evens.reduce((a, b) => a < b ? a : b);
  int minIndex = arr.indexOf(minEven);

  return [minEven, minIndex];
}

